revset-aliases."trunk()" = '''
latest(
--
revset-aliases."builtin_log()" = 'present(@) | ancestors(immutable_heads().., 2) | trunk()'
revset-aliases."builtin_immutable_heads()" = 'trunk() | tags() | untracked_remote_bookmarks()'
revset-aliases."immutable()" = '::(immutable_heads() | root())'
revset-aliases."mutable()" = '~immutable()'
revset-aliases."visible()" = '::visible_heads()'
revset-aliases."hidden()" = '~visible()'
templates.bookmark_list = 'format_commit_ref(self, "bookmark") ++ "\n"'
templates.commit_summary = 'format_commit_summary_with_refs(self, format_commit_ref_names(bookmarks))'
templates.arrange = 'builtin_log_compact'
--
      if(commit.immutable(), "immutable", "mutable"),
      if(commit.conflict(), "conflicted"),
    ),
    separate(" ",
      format_short_change_id_with_change_offset(commit),
      format_short_signature_oneline(commit.author()),
--
      if(commit.immutable(), "immutable", "mutable"),
      if(commit.conflict(), "conflicted"),
    ),
    concat(
      format_short_commit_header(commit) ++ "\n",
      separate(" ",
--
      if(commit.immutable(), "immutable", "mutable"),
      if(commit.conflict(), "conflicted"),
    ),
    concat(
      format_short_commit_header_redacted(commit) ++ "\n",
      separate(" ",
--
      if(commit.immutable(), "immutable", "mutable"),
      if(commit.conflict(), "conflicted"),
    ),
    concat(
      format_short_commit_header(commit) ++ "\n",
      separate(" ",
--
label("immutable",
  separate(" ",
    format_short_change_id(root.change_id()),
    label("root", "root()"),
    format_short_commit_id(root.commit_id()),
    root.bookmarks(),
--
      if(immutable, "immutable", "mutable"),
      if(conflict, "conflicted"),
    ),
    coalesce(
      if(current_working_copy, "@"),
      if(immutable, "◆"),
      if(conflict, "×"),
      "○",
    )
  )
)
--
      if(immutable, "immutable", "mutable"),
      if(conflict, "conflicted"),
    ),
    coalesce(
      if(current_working_copy, "@"),
      if(immutable, "+"),
      if(conflict, "x"),
      "o",
    )
  )
)
--
revset-aliases."immutable_heads()" = "bookmarks()"

